#!/usr/bin/env bash
# ============================================================================
#  GSZ step109 — category drag-to-reorder (finishes "full category controls").
#  Adds a dependency-free drag handle to the category list; the new order is
#  saved and used across the storefront. Reusable admin-sort.js for products
#  next. Safe + idempotent; restores previous files on any failure.
# ============================================================================
set -euo pipefail
GSZ=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BK="$GSZ/.bak-step109-$TS"
TMP=$(mktemp -d)
FILES=(routes/adminCatalog.js views/admin/categories.ejs)
ASORT=public/js/admin-sort.js

echo "==> step109: category drag-to-reorder"
mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
HAD_ASORT=0; if [ -f "$GSZ/$ASORT" ]; then HAD_ASORT=1; cp "$GSZ/$ASORT" "$BK/asort.prev"; fi
echo "    backup: $BK"

restore() {
  echo "!!  FAILED — restoring previous files"
  for f in "${FILES[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  if [ "$HAD_ASORT" = "1" ]; then cp "$BK/asort.prev" "$GSZ/$ASORT"; else rm -f "$GSZ/$ASORT"; fi
  pm2 restart gsz >/dev/null 2>&1 || true
  echo "!!  restored. no changes kept."
}
trap 'restore' ERR

echo "" | base64 -d > "$TMP/patch_step109.js"

echo "==> applying patches"
node "$TMP/patch_step109.js" "$GSZ"

echo "==> writing admin-sort.js + categories.ejs"
mkdir -p "$GSZ/public/js"
echo "" | base64 -d > "$GSZ/$ASORT"
echo "" | base64 -d > "$GSZ/views/admin/categories.ejs"

echo "==> validating"
node --check "$GSZ/routes/adminCatalog.js"
node --check "$GSZ/$ASORT"
node -e "const ejs=require('$GSZ/node_modules/ejs');ejs.compile(require('fs').readFileSync('$GSZ/views/admin/categories.ejs','utf8'),{filename:'$GSZ/views/admin/categories.ejs'});console.log('    categories.ejs ok')"

echo "==> restarting app"
pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
sleep 2

echo "==> health checks"
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true)
[ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }

SC=$(curl -s http://127.0.0.1:3900/static/js/admin-sort.js || true)
grep -q 'adminSort' <<<"$SC" && echo "    admin-sort.js serves: OK" || { echo "    admin-sort.js not served"; false; }

AC=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/admin/categories || true)
[ "$AC" = "200" ] || [ "$AC" = "302" ] && echo "    /admin/categories reachable ($AC): OK" || { echo "    /admin/categories $AC"; false; }

trap - ERR
rm -rf "$TMP"
echo ""
echo "==> step109 OK ✅"
echo "    • Categories page now has a drag handle — drag rows to reorder."
echo "    • Order saves instantly and is the order shown across the storefront."
echo "    • Add / edit / hide / show / delete already worked; ordering completes #6."
